<?php
namespace App\Http\Controllers\Api\V1;use App\Models\ServiceCategory;use Illuminate\Http\Request;class ServiceCategoryController extends ApiController{public function index(){return $this->success(ServiceCategory::where('status','ACTIVE')->orderBy('sort_order')->get());}public function store(Request $r){$this->admin($r);$d=$r->validate(['name'=>'required|string|max:255|unique:service_categories,name','description'=>'nullable|string','status'=>'nullable|in:ACTIVE,INACTIVE','sort_order'=>'nullable|integer|min:0']);return $this->success(ServiceCategory::create($d),[]);}public function update(Request $r,ServiceCategory $category){$this->admin($r);$d=$r->validate(['name'=>'sometimes|string|max:255|unique:service_categories,name,'.$category->id,'description'=>'nullable|string','status'=>'nullable|in:ACTIVE,INACTIVE','sort_order'=>'nullable|integer|min:0']);$category->update($d);return $this->success($category->fresh());}private function admin(Request $r){abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);}}
